/**
 * @param {number} n
 * @param {number[]} nums
 * @param {number} maxDiff
 * @param {number[][]} queries
 * @return {boolean[]}
 */
var pathExistenceQueries = function(n, nums, maxDiff, queries) {
    const res = [];

    for (const [u, v] of queries) {
        let con = true;

        for (let i = Math.min(u, v); i < Math.max(u, v); i++) {
            if (Math.abs(nums[i] - nums[i + 1]) > maxDiff) {
                con = false;
                break;
            }
        }

        res.push(con);
    }

    return res;
};

/**
 * @param {number} n
 * @param {number[]} nums
 * @param {number} maxDiff
 * @param {number[][]} queries
 * @return {boolean[]}
 */
var pathExistenceQueries = function (n, nums, maxDiff, queries) {
    const groups = Array(n).fill(0);
    let curr = 0;

    for (let i = 1; i < n; i++) {
        if (nums[i] - nums[i - 1] > maxDiff) {
            curr++;
        }
        groups[i] = curr;
    }

    const res = [];

    for (const [u, v] of queries) {
        res.push(groups[u] === groups[v]);
    }

    return res;
};
